def make_palindrome(string: str) -> str:
    if not string:
        return ''

    def longest_palindrome_suffix(s: str) -> int:
        for i in range(len(s)):
            if is_palindrome(s[i:]):
                return i
        return len(s)

    suffix_start = longest_palindrome_suffix(string)
    to_append = string[:suffix_start][::-1]
    return string + to_append

